const select = document.getElementById(
  "casino-meta-banner-select",
) as HTMLSelectElement | null;
const panels = Array.from(
  document.querySelectorAll<HTMLElement>("[data-casino-meta-banner]"),
);

const setActiveBanner = (value: string) => {
  panels.forEach((panel) => {
    panel.classList.toggle("hidden", panel.dataset.casinoMetaBanner !== value);
  });
};

if (select && panels.length) {
  setActiveBanner(select.value);
  select.addEventListener("change", (event) => {
    setActiveBanner((event.target as HTMLSelectElement).value);
  });
}
